## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/therapeuticEUSLogic.ts`

```typescript
/**
 * Therapeutic EUS (EUS-Guided Biliary Drainage) Clinical Logic Engine
 * Based on: ASGE Guideline on EUS-Guided Biliary and Pancreatic Duct Interventions (2022, 2025 Update)
 *           ESGE Guideline on EUS-Guided Biliary Drainage (2022)
 *           ASGE Guideline on LAMS (Lumen-Apposing Metal Stents) (2021, 2024 Update)
 * Key decisions: EUS-BD vs ERCP vs percutaneous, LAMS selection,
 *                EUS-guided pancreatic duct drainage, EUS-guided gallbladder drainage
 */

export type BiliaryDrainageIndication =
  | 'ercp_failure' // Failed ERCP (most common indication for EUS-BD)
  | 'altered_anatomy' // Roux-en-Y, Whipple, gastric bypass
  | 'malignant_biliary_obstruction' // Pancreatic cancer, cholangiocarcinoma
  | 'benign_biliary_stricture'
  | 'choledocholithiasis_ercp_failed'
  | 'gallbladder_drainage'; // Acute cholecystitis — surgical high risk

export type ERCPFailureReason =
  | 'failed_cannulation' // Cannot access papilla
  | 'failed_stone_clearance' // Stones too large
  | 'altered_anatomy_access' // Cannot reach papilla
  | 'duodenal_obstruction' // Tumor obstructing duodenum
  | 'not_attempted'; // EUS-BD as first-line

export type EUSBDApproach =
  | 'choledochoduodenostomy' // EUS-CDS: CBD to duodenum (most common)
  | 'hepaticogastrostomy' // EUS-HGS: left hepatic duct to stomach
  | 'antegrade_stenting' // EUS-AG: wire through papilla antegrade
  | 'rendezvous' // EUS-RV: wire through papilla, ERCP completes
  | 'gallbladder_drainage' // EUS-GBD with LAMS
  | 'pancreatic_duct_drainage'; // EUS-PD

export type ObstructionLevel =
  | 'distal_cbd' // Below cystic duct — accessible for EUS-CDS
  | 'hilar' // Bismuth I–IV
  | 'intrahepatic'
  | 'gallbladder'
  | 'pancreatic_duct';

export interface TherapeuticEUSInput {
  // Indication
  indication: BiliaryDrainageIndication;
  erpFailureReason: ERCPFailureReason;
  obstructionLevel: ObstructionLevel;

  // Anatomy
  hasAlteredAnatomy: boolean;
  alteredAnatomyType?: 'roux_en_y' | 'whipple' | 'billroth_ii' | 'gastric_bypass' | 'other';
  cbdDiameterMm?: number; // ≥12mm = dilated, favorable for EUS-CDS
  hasIntrahepticDilation: boolean;
  hasAscites: boolean; // Relative contraindication for EUS-HGS
  hasPriorBiliaryStent: boolean;
  priorStentType?: 'plastic' | 'sems_covered' | 'sems_uncovered';

  // Malignancy context
  hasMalignantObstruction: boolean;
  malignancyType?: 'pancreatic_cancer' | 'cholangiocarcinoma' | 'ampullary' | 'gallbladder' | 'metastatic' | 'other';
  isResectable: boolean;
  expectedSurvivalMonths?: number;

  // Gallbladder drainage
  hasAcuteCholecystitis: boolean;
  isSurgicalHighRisk: boolean; // Frail, comorbid — cannot tolerate cholecystectomy
  hasCysticDuctObstruction: boolean;
  gallbladderAccessibleByEUS: boolean;

  // Pancreatic duct
  hasPancreaticDuctDilation: boolean;
  pdDiameterMm?: number;
  hasPancreaticDuctStricture: boolean;
  hasPancreaticFistula: boolean;
  hasDisconnectedPancreaticDuctSyndrome: boolean;

  // Patient factors
  hasCoagulopathy: boolean;
  inrValue?: number;
  plateletCount?: number;
  isOnAnticoagulation: boolean;
  performanceStatus: 'good' | 'moderate' | 'poor';
  ageYears: number;

  // Prior interventions
  hasPriorEUSBD: boolean;
  hasPriorPercutaneousDrainage: boolean;
  hasPriorERCP: boolean;
  numberOfPriorERCPAttempts?: number;
}

export interface TherapeuticEUSRecommendation {
  primaryRecommendation: string;
  eusBDApproach: string;
  stentSelection: string;
  procedureSequence: string;
  alternativeApproach: string;
  postProcedureManagement: string;
  adverseEventRisk: string;
  urgentFlags: string[];
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessTherapeuticEUS(input: TherapeuticEUSInput): TherapeuticEUSRecommendation {
  const urgentFlags: string[] = [];
  const nextSteps: string[] = [];

  // ─── Urgent Flags ─────────────────────────────────────────────────────────
  if (input.hasCoagulopathy && input.inrValue !== undefined && input.inrValue > 1.5) {
    urgentFlags.push(`Coagulopathy (INR ${input.inrValue}): correct to INR <1.5 before EUS-BD — FFP, vitamin K, or hold anticoagulation`);
  }
  if (input.plateletCount !== undefined && input.plateletCount < 50000) {
    urgentFlags.push(`Thrombocytopenia (platelets ${input.plateletCount}): transfuse to >50,000 before EUS-BD`);
  }
  if (input.hasAcuteCholecystitis && !input.isSurgicalHighRisk) {
    urgentFlags.push('Acute cholecystitis in surgical candidate: laparoscopic cholecystectomy is preferred over EUS-GBD — consult surgery');
  }
  if (input.indication === 'malignant_biliary_obstruction' && input.isResectable) {
    urgentFlags.push('Resectable malignancy: biliary drainage should be performed only if surgery delayed >2 weeks or jaundice severe — avoid pre-op stenting if surgery within 2 weeks (increases infection risk)');
  }

  // ─── EUS-BD Approach Selection ────────────────────────────────────────────
  let eusBDApproach = '';
  let stentSelection = '';
  let procedureSequence = '';

  if (input.indication === 'gallbladder_drainage' || input.hasAcuteCholecystitis) {
    eusBDApproach =
      'EUS-GUIDED GALLBLADDER DRAINAGE (EUS-GBD) with LAMS (ASGE 2024): ' +
      'Indication: acute cholecystitis in surgical high-risk patients. ' +
      'Approach: transgastric or transduodenal access to gallbladder. ' +
      'LAMS (lumen-apposing metal stent): Hot AXIOS or SPAXUS — creates fistula between GI lumen and gallbladder. ' +
      'Technical success: 93–98%. Clinical success: 90–95%. ' +
      'Advantages over percutaneous cholecystostomy: no external drain, better quality of life, comparable efficacy. ' +
      'ENDOCATCH trial (2024): EUS-GBD superior to percutaneous drainage for clinical success and adverse events.';
    stentSelection =
      'LAMS selection for EUS-GBD: ' +
      'Hot AXIOS 10mm × 10mm or 15mm × 10mm (most commonly used). ' +
      'Electrocautery-enhanced delivery system (Hot AXIOS) — single-step deployment. ' +
      'Remove stent at 4 weeks if patient becomes surgical candidate.';
    nextSteps.push('EUS-GBD with LAMS (Hot AXIOS)', 'Surgical consultation for interval cholecystectomy');
  } else if (input.obstructionLevel === 'distal_cbd' && input.cbdDiameterMm !== undefined && input.cbdDiameterMm >= 12) {
    eusBDApproach =
      'EUS-CHOLEDOCHODUODENOSTOMY (EUS-CDS) — PREFERRED for distal CBD obstruction (ASGE 2025): ' +
      'Most common EUS-BD approach (70–80% of EUS-BD cases). ' +
      'Requires: dilated CBD ≥12mm, accessible from duodenal bulb. ' +
      'Approach: 19G needle → wire → dilation → LAMS or SEMS deployment. ' +
      'Technical success: 90–95%. Clinical success: 85–92%. ' +
      'ELEMENT trial (2023): EUS-CDS non-inferior to ERCP for malignant distal biliary obstruction. ' +
      'DRAINBIL trial: EUS-CDS superior to PTBD for ERCP failure.';
    stentSelection =
      'Stent selection for EUS-CDS: ' +
      '1) LAMS (Hot AXIOS 6mm × 8mm or 8mm × 8mm): preferred for benign disease or short-term drainage. ' +
      '2) SEMS (covered or partially covered): preferred for malignant obstruction — longer patency. ' +
      '3) Plastic stent: not recommended for EUS-CDS (higher migration risk).';
    nextSteps.push('EUS-CDS with SEMS (malignant) or LAMS (benign/short-term)', 'Post-procedure LFTs at 48h and 1 week');
  } else if (input.hasIntrahepticDilation || input.hasAlteredAnatomy) {
    eusBDApproach =
      'EUS-HEPATICOGASTROSTOMY (EUS-HGS) — for hilar obstruction or altered anatomy (ASGE 2025): ' +
      'Approach: transgastric access to left intrahepatic duct (B3 or B2). ' +
      'Indication: hilar obstruction, altered anatomy (Roux-en-Y, Whipple) where EUS-CDS not feasible. ' +
      'Technical success: 85–92%. Clinical success: 80–88%. ' +
      'Higher adverse event rate than EUS-CDS (bile leak, stent migration). ' +
      'Avoid if significant ascites (bile peritonitis risk).';
    stentSelection =
      'Stent selection for EUS-HGS: ' +
      'Partially covered SEMS (8–10mm × 60–80mm) — preferred for malignant hilar obstruction. ' +
      'Plastic stent: 7–10Fr for benign disease or bridge to surgery.';
    if (input.hasAscites) {
      urgentFlags.push('Ascites: EUS-HGS has higher bile leak risk with ascites — consider percutaneous transhepatic biliary drainage (PTBD) as alternative');
    }
    nextSteps.push('EUS-HGS with partially covered SEMS', 'Hepatology/IR consultation if EUS-HGS not feasible');
  } else if (input.indication === 'choledocholithiasis_ercp_failed') {
    eusBDApproach =
      'EUS-RENDEZVOUS (EUS-RV) for failed ERCP cannulation: ' +
      'EUS-guided wire access through papilla → wire retrieved at papilla → ERCP completes cannulation. ' +
      'Preferred when ERCP failure is due to difficult cannulation (not anatomy). ' +
      'Technical success: 75–85%. ' +
      'Alternative: EUS-antegrade stenting (EUS-AG) — wire advanced antegrade through stricture.';
    stentSelection = 'Plastic stent or SEMS depending on stricture etiology.';
    nextSteps.push('EUS-rendezvous technique', 'If rendezvous fails: EUS-CDS or EUS-HGS');
  } else if (input.obstructionLevel === 'pancreatic_duct' || input.hasPancreaticDuctDilation) {
    eusBDApproach =
      'EUS-GUIDED PANCREATIC DUCT DRAINAGE (EUS-PD) (ASGE 2025): ' +
      'Indication: failed ERCP for pancreatic duct stricture, disconnected pancreatic duct syndrome, chronic pancreatitis with MPD dilation. ' +
      'Approach: transgastric (body/tail) or transduodenal (head) access to MPD. ' +
      'Technical success: 75–85%. Clinical success: 70–80%. ' +
      'Technically demanding — requires expert interventional endoscopist. ' +
      'Disconnected pancreatic duct syndrome: LAMS preferred (creates fistula for sustained drainage).';
    stentSelection =
      'Stent for EUS-PD: ' +
      '5–7Fr plastic stent (standard). ' +
      'LAMS for disconnected duct syndrome.';
    nextSteps.push('EUS-PD at expert center', 'Surgical consultation for pancreatic duct drainage alternatives');
  } else {
    eusBDApproach = 'EUS-BD approach to be determined based on anatomy and ERCP findings. Interventional endoscopy consultation recommended.';
    stentSelection = 'Stent selection pending procedural planning.';
  }

  // ─── Procedure Sequence ───────────────────────────────────────────────────
  if (!procedureSequence) {
    procedureSequence =
      'PROCEDURE SEQUENCE (ASGE 2025): ' +
      '1) Confirm ERCP failure or contraindication before EUS-BD. ' +
      '2) Cross-sectional imaging (CT/MRCP) to plan approach. ' +
      '3) Correct coagulopathy (INR <1.5, platelets >50,000). ' +
      '4) Hold anticoagulation per procedural guidelines (5 days for warfarin; 24–48h for DOAC). ' +
      '5) EUS-BD performed under general anesthesia or deep sedation. ' +
      '6) Fluoroscopy guidance throughout procedure. ' +
      '7) Post-procedure: NPO 4–6h, IV antibiotics (ceftriaxone), LFTs at 24–48h.';
  }

  // ─── Alternative Approach ─────────────────────────────────────────────────
  const alternativeApproach =
    'ALTERNATIVES TO EUS-BD: ' +
    '1) Percutaneous transhepatic biliary drainage (PTBD): IR-guided, external drain. ' +
    '   Preferred if: EUS-BD technically not feasible, ascites, coagulopathy not correctable. ' +
    '   Higher adverse event rate than EUS-BD (bile leak, cholangitis, tube dislodgement). ' +
    '2) Surgical bypass: hepaticojejunostomy or choledochojejunostomy. ' +
    '   For: benign strictures, fit patients with long life expectancy. ' +
    '3) Repeat ERCP at expert center: if prior ERCP failed at non-expert center.';

  // ─── Post-Procedure Management ────────────────────────────────────────────
  const postProcedureManagement =
    'POST-PROCEDURE MANAGEMENT: ' +
    'IV antibiotics: ceftriaxone 1g IV x24–48h (or piperacillin-tazobactam for high-risk). ' +
    'LFTs at 24–48h and 1 week. ' +
    'CT abdomen if fever, pain, or LFT worsening (assess for bile leak, stent migration). ' +
    'Stent surveillance: SEMS — every 3–6 months; LAMS — remove at 4 weeks (benign) or leave for malignant. ' +
    'Stent occlusion: repeat EUS-BD or ERCP for stent exchange.';

  // ─── Adverse Event Risk ───────────────────────────────────────────────────
  const adverseEventRisk =
    'ADVERSE EVENTS (EUS-BD overall rate: 10–15%): ' +
    'Bile leak/peritonitis: 3–5% (most serious). ' +
    'Stent migration: 5–8% (LAMS higher than SEMS). ' +
    'Cholangitis/infection: 3–5%. ' +
    'Bleeding: 1–3%. ' +
    'Pneumoperitoneum: 2–3%. ' +
    'Stent occlusion (long-term): 15–25% at 6 months. ' +
    'EUS-BD adverse event rate is comparable to PTBD and lower than surgical bypass.';

  if (nextSteps.length === 0) {
    nextSteps.push(
      'Confirm ERCP failure documentation',
      'Cross-sectional imaging (CT/MRCP) for anatomy planning',
      'Correct coagulopathy before procedure',
      'Interventional endoscopy referral at expert center',
      'Multidisciplinary discussion (GI, surgery, IR)'
    );
  }

  const rationale =
    `Indication: ${input.indication.replace(/_/g, ' ')}. ` +
    `ERCP failure reason: ${input.erpFailureReason.replace(/_/g, ' ')}. ` +
    `Obstruction level: ${input.obstructionLevel.replace(/_/g, ' ')}. ` +
    `CBD diameter: ${input.cbdDiameterMm ? `${input.cbdDiameterMm}mm` : 'not measured'}. ` +
    `Altered anatomy: ${input.hasAlteredAnatomy ? 'Yes' : 'No'}. ` +
    `Malignant: ${input.hasMalignantObstruction ? 'Yes' : 'No'}.`;

  return {
    primaryRecommendation:
      input.hasAcuteCholecystitis && input.isSurgicalHighRisk
        ? 'Acute cholecystitis in surgical high-risk patient: EUS-guided gallbladder drainage (EUS-GBD) with LAMS — superior to percutaneous drainage (ENDOCATCH trial).'
        : input.indication === 'ercp_failure' && input.obstructionLevel === 'distal_cbd'
        ? 'ERCP failure with distal CBD obstruction: EUS-choledochoduodenostomy (EUS-CDS) is preferred approach — non-inferior to ERCP (ELEMENT trial).'
        : input.hasAlteredAnatomy
        ? 'Altered anatomy (Roux-en-Y/Whipple): EUS-BD is preferred over repeat ERCP — EUS-hepaticogastrostomy or EUS-antegrade stenting.'
        : 'Therapeutic EUS indicated: interventional endoscopy referral at expert center for EUS-guided biliary drainage.',
    eusBDApproach,
    stentSelection,
    procedureSequence,
    alternativeApproach,
    postProcedureManagement,
    adverseEventRisk,
    urgentFlags,
    nextSteps,
    evidenceLevel: 'B',
    rationale,
    references: [
      {
        citation: 'ASGE Standards of Practice Committee. The role of endoscopy in the management of choledocholithiasis. Gastrointest Endosc. 2019;89(6):1075-1105.',
        pmid: '30979521',
        url: 'https://pubmed.ncbi.nlm.nih.gov/30979521/',
      },
      {
        citation: 'Paik WH, et al. EUS-Guided Biliary Drainage vs ERCP for Malignant Biliary Obstruction (ELEMENT). Lancet Gastroenterol Hepatol. 2023;8(2):132-141.',
        pmid: '36462521',
        url: 'https://pubmed.ncbi.nlm.nih.gov/36462521/',
      },
      {
        citation: 'Teoh AYB, et al. EUS-Guided Gallbladder Drainage vs Percutaneous Cholecystostomy for Acute Cholecystitis (ENDOCATCH). Gut. 2024;73(1):50-58.',
        pmid: '37793794',
        url: 'https://pubmed.ncbi.nlm.nih.gov/37793794/',
      },
      {
        citation: 'Nakai Y, et al. International consensus statements for endoscopic management of distal biliary stricture. J Gastroenterol Hepatol. 2020;35(6):967-979.',
        pmid: '32162356',
        url: 'https://pubmed.ncbi.nlm.nih.gov/32162356/',
      },
    ],
  };
}
